from lib import *
S = SS('t24')
steps = [
    step("真实的 3 节点 etcd(3.7.2)上看一次正常写入的提交。写入之前,三个节点的 raft term 都是 2,raftIndex 和 raftAppliedIndex 都是 8,t24n2 是 leader。对 leader 写 5 次之后,三个节点的 raftIndex 和 raftAppliedIndex 都变成了 13。每次写入是一条 Raft 日志,leader 先追加,再复制给 follower,多数(3 个里的 2 个)落盘之后才算提交、才应用到状态机、才回复客户端。", t=tl(S(1)), mark=lidx(S(1), '对 leader 写了 5 次之后'), done=lidx(S(1), '写入之前', 'leader 是 t24n2'), b=bars([['写入前 raftIndex', 8, '8'], ['写 5 次后 raftIndex', 13, '13(三个节点相同)']], 13, cur=[0], done=[1]), kv=KV([['一次写入', '一条日志,复制到多数后提交'], ['5 次写入', 'raftIndex 8 → 13'], ['三个节点', 'raftIndex 都涨了 5']], ['5 次写入'])),
    step("杀掉一个 follower(t24n0,kill -9):剩下 2 个仍是多数,写入照常提交。对 leader 写 100 次,中位数 7.83 ms、p99 15.51 ms,杀之前是 7.74 ms、p99 17.75 ms,leader 没变。杀掉期间又写了 50 次,两个存活节点的 raftIndex 都是 263。重启 t24n0 之后 164 ms,它的 raftAppliedIndex 追上了 leader,三个节点都是 264。少一个节点不影响提交,落后的节点回来后由 leader 把缺的日志补给它。", t=tl(S(2)), mark=lidx(S(2), '杀掉 follower t24n0'), done=lidx(S(2), '重启 t24n0 之后'), b=bars([['杀之前 写入中位数 ms', 7.74, '7.74'], ['杀之后 写入中位数 ms', 7.83, '7.83'], ['重启后追上用时 ms', 164, '164']], 170, cur=[0, 1], done=[2]), kv=KV([['杀 1 个 follower', '写入延迟几乎不变'], ['期间', '2 个存活节点 raftIndex 263'], ['重启', '164 ms 追上,三个节点 264']], ['杀 1 个 follower'])),
    step("再杀掉两个节点,只剩 1 个(不再是多数)。对唯一存活的 t24n2 写 key = new:客户端等了 3.0 s 超时,提交不了;线性一致读也等了 3.0 s 超时,拿不到多数的确认;可串行化读(只读本节点自己的状态)返回 key = old,没提交的 new 没有生效。再过 2 秒,t24n2 报告的 leader 字段是 0——联系不上多数,自己让出了 leader。重启一个节点之后多数恢复,选出 t24n2 当 leader,此刻线性一致读 key = new:那次超时的写入已经是 leader 日志里的一条,多数恢复后被提交了。所以“超时”不等于“没写成功”,只表示“不知道”。这次是持有那条日志的节点赢了选举;如果赢的是日志更短的节点,这条没提交的写入可能被丢掉,我没有造出那种情形。", t=tl(S(3)), mark=lidx(S(3), '写 key = new', '线性一致读 key:TimeoutError'), done=lidx(S(3), '重启一个节点', '客户端那次写入'), b=bars([['写入超时等待 s', 3.0, '3.0'], ['可串行化读到的 key', 1, 'old(new 未生效)'], ['多数恢复后线性一致读到的 key', 2, 'new(之前超时的写入被提交)']], 3, mark=[0], cur=[1], done=[2]), kv=KV([['只剩 1 个节点', '写入、线性一致读都超时'], ['leader 字段', '2 秒后变 0,自己让出了 leader'], ['多数恢复后', '之前超时的写入被提交了']], ['多数恢复后'])),
    step("Raft 论文图 8 的场景(手写的 5 节点日志模拟,不是 etcd):S1 在任期 2 把位置 2 的条目复制给了 S2;S1 宕机,S5 在任期 3 当选并在位置 2 写了自己的条目;S5 宕机,S1 重启在任期 4 当选,把位置 2(任期 2)复制给 S3,现在 S1、S2、S3 多数都有它。规则 A(只要复制到多数就提交):S1 把位置 2 标成已提交并应用;随后 S1 宕机,S5 在任期 5 竞选并当选(S2、S3、S4 认为它的日志不比自己旧),把位置 2 覆盖成任期 3——S1、S2、S3 上的任期变成 [3, 3, 3],已提交的条目被覆盖。规则 B(Raft 的规则:只有当前任期的条目才靠数副本数提交):S1 先在任期 4 追加位置 3 并复制到 S2、S3,位置 2 与 3 一起提交;这时 S5 的日志已经比多数旧,没能当选,位置 2 的任期仍是 [2, 2, 2]。", t=tl(S(4)), mark=lidx(S(4), '规则 A', '[3, 3, 3]'), done=lidx(S(4), '规则 B', '[2, 2, 2]'), b=bars([['规则 A:S5 是否当选', 1, '是'], ['规则 B:S5 是否当选', 0, '否'], ['规则 A:已提交条目被覆盖的节点数', 3, '3'], ['规则 B:已提交条目被覆盖的节点数', 0, '0']], 3, mark=[0, 2], done=[1, 3]), kv=KV([['规则 A', '旧任期条目靠数副本数提交 → 被覆盖'], ['规则 B', '只有当前任期的条目靠数副本提交'], ['旧条目', '随当前任期的条目一起提交']], ['规则 B'])),
    step("提交只等“最快的多数”。换一个全新的 3 节点集群,在 peer 通信上加延迟(代理按“被连接的一方”加延迟、每个方向都延迟),对 leader 写 40 次的中位数:不加延迟 8.1 ms;一个 follower 的 peer 地址 +20 ms:7.0 ms,几乎不变(leader 加上另一个 follower 就是多数);两个 follower 各 +20 ms:31.0 ms;一个 +20 ms、一个 +60 ms:31.5 ms,和两个都 +20 差不多——等的是较快的那个;leader 的 peer 地址 +20 ms:28.2 ms;三个节点都 +20 ms:52.7 ms。提交的延迟取决于最快的多数,而不是最慢的那个节点。各配置具体延迟了哪条路径(AppendEntries 还是确认)我没有逐条验证。", t=tl(S(5)), mark=lidx(S(5), '两个 follower:+20 ms 和 +60 ms'), done=lidx(S(5), '不加延迟', '一个 follower(t24n0)'), b=bars([['不加延迟 ms', 8.1, '8.1'], ['一个 follower +20 ms', 7.0, '7.0'], ['两个 follower 各 +20 ms', 31.0, '31.0'], ['一个 +20 ms、一个 +60 ms', 31.5, '31.5']], 55, cur=[0, 1], mark=[2, 3]), kv=KV([['一个 follower 慢', '延迟不变'], ['两个 follower 都慢', '延迟随较快的那个升到约 31 ms'], ['+20 与 +60', '和两个 +20 差不多,等的是较快的']], ['两个 follower 都慢'])),
]
A = mkartt('t24', 24, '分布式事务,Raft,日志复制,提交条件,etcd,线性一致,真实验证,动画演示',
    '用真实的 3 节点 etcd 实测 Raft 的提交条件:多数(2/3)落盘才提交;杀 1 个 follower 写入延迟不变(7.74 → 7.83 ms)、重启后 164 ms 追上;只剩 1 个节点时写入超时,多数恢复后那次超时的写入反而被提交;手写模拟论文图 8:数副本数提交旧任期条目会被覆盖;延迟只取决于最快的多数(31.0 vs 31.5 ms)。',
    '分布式事务里的 TC、元数据、全局状态常常放在 Raft 复制的存储里。Raft 的“提交”到底是什么条件?少数节点挂掉会怎样?多数丢了会怎样?为什么旧任期的日志不能靠数副本数提交?这篇用真实的 etcd 和一个手写的日志模拟,把这些问题逐个跑出来。',
    [('7.74 → 7.83 ms', '杀掉 1 个 follower 前后,3 节点 etcd 的写入延迟中位数(没有变化)'), ('3.0 s 超时 → 之后 new', '只剩 1 个节点时那次写入客户端超时;多数恢复后线性一致读到的却是 new'), ('[3, 3, 3]', '手写模拟图 8:规则 A 下已提交的位置 2 条目被覆盖后,S1、S2、S3 上它的任期')],
    [('提交 = 多数落盘', '<p>leader 追加日志、复制给 follower,多数节点落盘后才提交、应用、回复客户端;三个节点的 raftIndex 同步增长。</p>'),
     ('少数挂掉不影响', '<p>杀掉 1 个 follower,写入延迟几乎不变;它回来后由 leader 补日志。</p>'),
     ('多数丢了', '<p>只剩 1 个节点时写入、线性一致读都超时,leader 让出角色;可串行化读只读本地。多数恢复后,之前超时的那条写入被提交——超时只代表不知道。</p>'),
     ('旧任期的日志', '<p>图 8:靠数副本数提交上一任期的条目,会被后来者覆盖;Raft 规定只有当前任期的条目才靠数副本数提交,旧条目随之一起提交。</p>'),
     ('最快的多数', '<p>提交延迟取决于最快的多数,慢节点不拖累:一个 follower +20 ms 延迟不变,两个都慢才升高。</p>')],
    steps,
    [ENV_T + '。本篇第一、二、三、五节用真实的 etcd 3.7.2(3 个节点,heartbeat-interval 100 ms、election-timeout 1000 ms),通过 etcd 的 HTTP/JSON 网关读写,kill -9 杀进程;peer 地址经过我加的一层延迟代理(只在第五节用来加延迟);第四节是我按 Raft 论文图 8 手写的 5 节点日志模拟(任期、投票的“日志不比自己旧”检查、AppendEntries 覆盖),不是 etcd',
     '没有验证:etcd 里同一场景(图 8)的真实表现;磁盘 fsync 对提交延迟的影响(mac 上 fsync 偏快);选举超时的随机化、PreVote、CheckQuorum 的细节(第三节 leader 让出角色是观察结果,没有读源码确认机制);成员变更与 learner;网络分区(这里只杀进程和加延迟);第三节“那条超时的写入被提交”只在持有它的节点赢得选举时成立,另一种情形没有造出来'],
    'Raft 提交')
